import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.some.js";
import { computed, ref, onMounted, watch } from 'vue';
import { useStore } from 'vuex';
import { useRouter } from 'vue-router';
import defaultAvatar from '@/assets/default-avatar.png';
import { API_CONFIG } from '@/config/config';
import axios from 'axios';
import { ElMessage } from 'element-plus';
import { debounce } from 'lodash';
import { useIntersectionObserver } from '@vueuse/core';
export default {
  setup() {
    const store = useStore();
    const router = useRouter();

    // 状态管理
    const isUserInfoOpen = ref(false);
    const isSearchOpen = ref(false);
    const searchKeyword = ref('');
    const searchResults = ref([]);
    const isSearching = ref(false);
    const isRecentChatCollapse = ref(false);
    const isJoinedGroupsCollapse = ref(false);
    const showCreateGroupDialog = ref(false);
    const groupSearchKeyword = ref('');
    const groupName = ref('');
    const selectedUsers = ref([]);
    const allUsers = ref([]);

    // 分页控制
    const pagination = ref({
      page: 1,
      pageSize: 10,
      total: 0,
      loading: false,
      hasMore: true
    });
    const loadMoreTrigger = ref(null);

    // 计算属性
    const user = computed(() => store.state.user);
    const displayName = computed(() => user.value?.username || '未登录');
    const recentChats = computed(() => {
      const chats = store.getters['chat/getRecentChats'] || [];
      return chats.map(chat => ({
        ...chat,
        avatarMembers: chat.avatar_members || [] // 确保有avatarMembers字段
      }));
    });
    const joinedGroups = computed(() => {
      const groups = store.getters['chat/getJoinedGroups'];
      console.log("groups : ", groups);
      return groups.map(group => ({
        ...group,
        avatarMembers: group.avatar_members || [] // 确保有avatarMembers字段
      }));
    });
    const isUserLoggedIn = computed(() => !!user.value?.id);
    const avatarUrl = computed(() => {
      if (user.value?.photo) {
        return `${API_CONFIG.BASE_URL}${user.value.photo}`;
      }
      return defaultAvatar;
    });

    // 方法定义
    const getFullUrl = path => {
      if (!path || path === defaultAvatar) return path;
      return path.startsWith('http') ? path : `${API_CONFIG.BASE_URL}${path}`;
    };
    const getGroupAvatar = async groupId => {
      try {
        const avatarMembers = await store.dispatch('chat/fetchGroupAvatar', groupId);
        console.log("avatars: ", avatarMembers);
        return avatarMembers || [];
      } catch (error) {
        console.error('获取群头像失败:', error);
        return [];
      }
    };
    const getGroupAvatarUrls = chat => {
      if (!chat) return []; // 防御性检查
      console.log("获取群信息chat: ", chat); // 有群聊信息id
      // 优先使用 avatarMembers
      if (chat.avatarMembers && chat.avatarMembers.length > 0) {
        return chat.avatarMembers.map(url => getFullUrl(url)).filter(Boolean);
      }

      // 如果没有 avatarMembers，使用成员ID获取头像
      const members = chat.group_members || chat.members || [];
      return getFirstMembers(members, 9).map(memberId => getMemberAvatar(memberId));
    };
    // 修改getMemberAvatar方法
    const getMemberAvatar = memberId => {
      // 先检查是否是当前用户
      if (memberId === user.value?.id) {
        return avatarUrl.value;
      }

      // 检查 allUsers 中是否有该成员
      const member = allUsers.value.find(u => u.id === memberId);

      // 如果有成员信息且包含头像，则返回头像URL
      if (member?.photo) {
        return getFullUrl(member.photo);
      }

      // 否则返回默认头像
      return defaultAvatar;
    };
    const getFirstMembers = (members, count) => {
      if (!members) return [];
      return members.slice(0, count);
    };
    const getAvatarPosition = index => {
      const positions = [{
        top: '0%',
        left: '0%',
        width: '50%',
        height: '50%'
      }, {
        top: '0%',
        left: '50%',
        width: '50%',
        height: '50%'
      }, {
        top: '50%',
        left: '0%',
        width: '50%',
        height: '50%'
      }, {
        top: '50%',
        left: '50%',
        width: '50%',
        height: '50%'
      }, {
        top: '16%',
        left: '16%',
        width: '33%',
        height: '33%'
      }, {
        top: '16%',
        right: '16%',
        width: '33%',
        height: '33%'
      }, {
        bottom: '16%',
        left: '16%',
        width: '33%',
        height: '33%'
      }, {
        bottom: '16%',
        right: '16%',
        width: '33%',
        height: '33%'
      }, {
        top: '33%',
        left: '33%',
        width: '33%',
        height: '33%'
      }];
      return positions[index] || positions[0];
    };
    const loadAllUsers = async () => {
      try {
        if (!pagination.value.hasMore || pagination.value.loading) {
          return;
        }
        pagination.value.loading = true;
        const response = await axios.get(`${API_CONFIG.BASE_URL}/user/get-users`, {
          params: {
            page: pagination.value.page,
            page_size: pagination.value.pageSize
          },
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        }).catch(error => {
          throw new Error(`请求失败: ${error.message}`);
        });
        const userList = (() => {
          try {
            const data = response?.data ?? {};
            if (Array.isArray(data)) return data;
            if (Array.isArray(data.data)) return data.data;
            if (Array.isArray(data.users)) return data.users;
            if (Array.isArray(data.list)) return data.list;
            if (Array.isArray(data.items)) return data.items;
            return [];
          } catch (e) {
            console.error('数据解析错误:', e);
            return [];
          }
        })();
        const total = (() => {
          try {
            const data = response?.data ?? {};
            return data.pagination?.total ?? data.total ?? data.total_count ?? data.totalItems ?? (userList.length > 0 ? Infinity : 0);
          } catch (e) {
            console.error('总数解析错误:', e);
            return userList.length > 0 ? Infinity : 0;
          }
        })();
        allUsers.value = pagination.value.page === 1 ? [...userList] : [...allUsers.value, ...userList];
        pagination.value.total = total;
        const receivedCount = userList.length;
        const isLastPage = receivedCount === 0 || total !== Infinity && pagination.value.page * pagination.value.pageSize >= total;
        pagination.value.hasMore = !isLastPage;
        if (receivedCount === 0 && total === Infinity) {
          pagination.value.hasMore = false;
          console.warn('没有获取到数据，已自动停止加载更多');
        }
      } catch (error) {
        console.error('加载用户列表失败:', error);
        ElMessage.error(error.message);
        pagination.value.hasMore = false;
        if (pagination.value.page === 1) {
          allUsers.value = [];
        }
      } finally {
        pagination.value.loading = false;
      }
    };
    const openCreateGroupDialog = async () => {
      showCreateGroupDialog.value = true;
      groupName.value = '';
      selectedUsers.value = [];
      groupSearchKeyword.value = '';
      pagination.value.page = 1;
      pagination.value.hasMore = true;
      await loadAllUsers();
    };
    const filteredUsers = computed(() => {
      if (!groupSearchKeyword.value.trim()) {
        return allUsers.value;
      }
      const keyword = groupSearchKeyword.value.toLowerCase().trim();
      return allUsers.value.filter(u => u.username.toLowerCase().includes(keyword) || u.phone && u.phone.includes(keyword));
    });
    const toggleUserSelection = user => {
      const index = selectedUsers.value.findIndex(u => u.id === user.id);
      if (index === -1) {
        selectedUsers.value.push(user);
      } else {
        selectedUsers.value.splice(index, 1);
      }
    };
    const isUserSelected = userId => {
      return selectedUsers.value.some(u => u.id === userId);
    };
    const removeUser = userId => {
      selectedUsers.value = selectedUsers.value.filter(u => u.id !== userId);
    };
    const createGroup = async () => {
      if (selectedUsers.value.length < 2) {
        ElMessage.warning('至少选择2位成员');
        return;
      }
      try {
        const groupMembers = selectedUsers.value.map(u => u.id);
        groupMembers.push(user.value.id);
        const groupData = {
          name: groupName.value || `群聊 (${selectedUsers.value.length + 1}人)`,
          user_id: user.value.id,
          members: groupMembers
        };
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/create`, groupData, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        console.log("response: ", response.data);
        console.log("response.data: ", response.data.data);
        if (response.data.msg) {
          ElMessage.success('群聊创建成功');
          const groupInfo = {
            id: response.data.data.group_id,
            username: groupData.name,
            photo: response.data.photo || null,
            isGroup: true,
            members: groupMembers
          };
          console.log("groupInfo: ", groupInfo);
          store.commit('chat/ADD_RECENT_CHAT', groupInfo);
          await store.dispatch('chat/saveRecentChat', groupInfo);
          showCreateGroupDialog.value = false;
          router.push({
            name: 'GroupChat',
            params: {
              groupId: response.data.data.group_id
            }
          });
        } else {
          ElMessage.error('群聊创建失败: ' + response.data.message);
        }
      } catch (error) {
        console.error('创建群聊失败:', error);
        ElMessage.error('群聊创建失败，请重试');
      }
    };
    const logout = () => {
      store.dispatch('logout');
      router.push('/login');
    };
    const goToUserDetail = () => {
      router.push('/user/userinfo/' + user.value?.id);
    };
    const toggleUserInfo = () => {
      isUserInfoOpen.value = !isUserInfoOpen.value;
    };
    const toggleSearch = () => {
      isSearchOpen.value = !isSearchOpen.value;
      if (!isSearchOpen.value) {
        searchKeyword.value = '';
        searchResults.value = [];
      }
    };
    const searchUsers = async () => {
      if (!searchKeyword.value.trim()) {
        searchResults.value = [];
        return;
      }
      isSearching.value = true;
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/user/search`, {
          params: {
            keyword: searchKeyword.value.trim()
          },
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        searchResults.value = response.data.data || [];
      } catch (error) {
        console.error('搜索用户失败:', error);
        ElMessage.error('搜索用户失败');
      } finally {
        isSearching.value = false;
      }
    };
    const debouncedSearchUsers = debounce(searchUsers, 300);
    const clearSearch = () => {
      searchKeyword.value = '';
      searchResults.value = [];
    };
    const loadRecentChats = async () => {
      try {
        await store.dispatch('chat/loadRecentChats');
        await store.dispatch('chat/loadJoinedGroups');
      } catch (error) {
        console.error('加载聊天数据失败:', error);
      }
    };

    // 在setup()中
    const getGroupAvatarMembers = async groupId => {
      try {
        const avatarMembers = await store.dispatch('chat/fetchGroupAvatar', groupId);
        return avatarMembers || [];
      } catch (error) {
        console.error('获取群头像成员失败:', error);
        return [];
      }
    };
    const startChat = async chat => {
      const newChat = {
        ...chat
      };

      // 确保ID是数字类型
      newChat.id = typeof chat.id === 'string' ? parseInt(chat.id, 10) : chat.id;
      console.log("群信息: ", newChat);

      // 对于群聊，确保有members信息
      if (chat.isGroup) {
        // 获取群成员头像URL列表
        newChat.avatarMembers = await getGroupAvatarMembers(chat.id);
        console.log("newChat 时群信息", newChat); //获取不到群信息

        // 从已加入群聊中获取完整信息
        const joinedGroup = store.getters['chat/getJoinedGroupById'](newChat.id);
        if (joinedGroup) {
          newChat.members = joinedGroup.members || [];
          newChat.membersCount = joinedGroup.membersCount || 0;
        }
      }

      // 保存到最近聊天
      store.commit('chat/ADD_RECENT_CHAT', newChat);
      await store.dispatch('chat/saveRecentChat', newChat);

      // 清除未读计数
      await store.dispatch('chat/clearUnreadCount', newChat.id);

      // 如果是搜索状态，重置搜索
      if (isSearchOpen.value) {
        isSearchOpen.value = false;
        searchKeyword.value = '';
        searchResults.value = [];
      }

      // 路由跳转

      router.push({
        name: chat.isGroup ? 'GroupChat' : 'Chat',
        params: {
          userId: newChat.id
        } //单独聊天
      });
    };
    const toggleRecentChatCollapse = () => {
      isRecentChatCollapse.value = !isRecentChatCollapse.value;
    };
    const toggleJoinedGroupsCollapse = () => {
      isJoinedGroupsCollapse.value = !isJoinedGroupsCollapse.value;
    };

    // 生命周期钩子
    onMounted(() => {
      useIntersectionObserver(loadMoreTrigger, ([{
        isIntersecting
      }]) => {
        if (isIntersecting && !pagination.value.loading && pagination.value.hasMore) {
          pagination.value.page += 1;
          loadAllUsers();
        }
      }, {
        threshold: 0.1
      });
      if (isUserLoggedIn.value) {
        loadRecentChats();
      }
    });
    watch(searchKeyword, newVal => {
      if (newVal.trim()) {
        debouncedSearchUsers();
      } else {
        searchResults.value = [];
      }
    });
    watch(user, newUser => {
      if (newUser?.id) {
        loadRecentChats();
      }
    });
    return {
      user,
      displayName,
      avatarUrl,
      getFullUrl,
      logout,
      goToUserDetail,
      isUserInfoOpen,
      toggleUserInfo,
      isSearchOpen,
      getGroupAvatar,
      getGroupAvatarUrls,
      searchKeyword,
      searchResults,
      isSearching,
      toggleSearch,
      clearSearch,
      startChat,
      defaultAvatar,
      recentChats,
      joinedGroups,
      isRecentChatCollapse,
      toggleRecentChatCollapse,
      isJoinedGroupsCollapse,
      toggleJoinedGroupsCollapse,
      showCreateGroupDialog,
      groupSearchKeyword,
      groupName,
      selectedUsers,
      filteredUsers,
      openCreateGroupDialog,
      toggleUserSelection,
      isUserSelected,
      removeUser,
      createGroup,
      getMemberAvatar,
      getFirstMembers,
      getAvatarPosition,
      pagination,
      loadMoreTrigger
    };
  },
  directives: {
    'click-outside': {
      mounted(el, binding) {
        el.clickOutsideEvent = function (event) {
          if (!(el === event.target || el.contains(event.target))) {
            binding.value(event);
          }
        };
        document.addEventListener('click', el.clickOutsideEvent);
      },
      unmounted(el) {
        document.removeEventListener('click', el.clickOutsideEvent);
      }
    }
  }
};
